// Package keys is the secp256k1 key surface the swap client needs.
//
// It wraps orly's p256k1 signer rather than implementing the curve: that
// implementation is pure Go, has a wasm build, provides BIP-340 Schnorr
// signatures and an ECDH that returns the raw x-coordinate — which is exactly
// the pair of operations NIP-44 and Nostr event signing require.
//
// Two deliberate choices live here:
//
//   - secret material is never generated by this package. Callers supply 32
//     bytes from a source they trust (crypto/rand on a host, WebCrypto in the
//     browser), because a wasm build's crypto/rand is not guaranteed to be a
//     good entropy source; and
//   - every returned slice is copied, because the underlying signer reuses its
//     signature buffer between calls.
package keys

import (
	"crypto/subtle"
	"encoding/hex"
	"fmt"
	"io"

	"git.smesh.lol/orly/pkg/p256k1/signer"
)

// SecretSize is the raw secret key size in bytes.
const SecretSize = 32

// PublicSize is the x-only public key size in bytes.
const PublicSize = 32

// SignatureSize is the BIP-340 signature size in bytes.
const SignatureSize = 64

// Key is a secret key with its derived x-only public key.
type Key struct {
	signer *signer.P256K1Signer
}

// FromSecret builds a key from 32 raw secret bytes.
//
// The secret is copied, and the signer normalises the key for BIP-340 (even Y),
// which is why the public key is the x-only form and the same secret always
// yields the same public key.
func FromSecret(secret []byte) (*Key, error) {
	if len(secret) != SecretSize {
		return nil, fmt.Errorf("secret key must be %d bytes", SecretSize)
	}

	s := signer.NewP256K1Signer()

	if err := s.InitSec(append([]byte{}, secret...)); err != nil {
		return nil, fmt.Errorf("secret key: %w", err)
	}

	return &Key{signer: s}, nil
}

// FromSecretHex builds a key from 64 hex characters.
func FromSecretHex(secretHex string) (*Key, error) {
	raw, err := hex.DecodeString(secretHex)

	if err != nil {
		return nil, fmt.Errorf("secret key must be hex")
	}

	return FromSecret(raw)
}

// PublicHex is the x-only public key as 64 lowercase hex characters.
func (k *Key) PublicHex() string {
	return hex.EncodeToString(k.signer.Pub())
}

// Public is a copy of the x-only public key bytes.
func (k *Key) Public() []byte {
	return append([]byte{}, k.signer.Pub()...)
}

// Secret is a copy of the normalised secret key bytes.
//
// It exists because durable state has to store the secret; callers that do not
// need it should hold the *Key and never call this.
func (k *Key) Secret() []byte {
	return append([]byte{}, k.signer.Sec()...)
}

// SecretHex is Secret as hex.
func (k *Key) SecretHex() string {
	return hex.EncodeToString(k.Secret())
}

// Sign signs a 32-byte message with BIP-340 Schnorr.
func (k *Key) Sign(message []byte) ([]byte, error) {
	signature, err := k.signer.Sign(message)

	if err != nil {
		return nil, err
	}

	// The signer reuses its buffer, so this copy is required.
	return append([]byte{}, signature...), nil
}

// Verify checks a BIP-340 signature against this key's public half.
//
// It deliberately does not use the library's verifier: see bip340.go for the
// TinyGo defect that made this necessary.
func (k *Key) Verify(message, signature []byte) (bool, error) {
	return verifyBIP340(k.signer.Pub(), message, signature), nil
}

// SharedX returns the raw 32-byte x-coordinate of the ECDH shared point with a
// peer x-only public key.
//
// NIP-44 hashes this with the label "nip44-v2"; the raw x-coordinate is the
// input, not a hashed form.
func (k *Key) SharedX(peerPublicHex string) ([]byte, error) {
	peer, err := hex.DecodeString(peerPublicHex)

	if err != nil {
		return nil, fmt.Errorf("peer public key must be hex")
	}

	if len(peer) != PublicSize {
		return nil, fmt.Errorf("peer public key must be %d bytes", PublicSize)
	}

	shared, err := k.signer.ECDHRaw(peer)

	if err != nil {
		return nil, fmt.Errorf("ECDH: %w", err)
	}

	return append([]byte{}, shared...), nil
}

// VerifySchnorr checks a signature against a public key without a secret.
//
// See bip340.go for why verification is implemented here rather than delegated
// to the curve library.
func VerifySchnorr(publicHex string, message, signature []byte) (bool, error) {
	pub, err := hex.DecodeString(publicHex)

	if err != nil {
		return false, fmt.Errorf("public key must be hex")
	}

	if len(pub) != PublicSize {
		return false, fmt.Errorf("public key must be %d bytes", PublicSize)
	}

	if len(message) != 32 {
		return false, fmt.Errorf("message must be 32 bytes")
	}

	if len(signature) != SignatureSize {
		return false, fmt.Errorf("signature must be %d bytes", SignatureSize)
	}

	return verifyBIP340(pub, message, signature), nil
}

// EqualSecrets compares two secret byte slices in constant time.
func EqualSecrets(a, b []byte) bool {
	return subtle.ConstantTimeCompare(a, b) == 1
}

// GenerateSecret reads a secret from r, for callers that have a randomness
// source of their own.
//
// This package does not generate secrets itself: on a host that source is
// crypto/rand, and in the browser it is WebCrypto. A wasm build's crypto/rand is
// not a guarantee worth resting key material on.
func GenerateSecret(r io.Reader) ([]byte, error) {
	secret := make([]byte, SecretSize)

	if _, err := io.ReadFull(r, secret); err != nil {
		return nil, fmt.Errorf("secret: %w", err)
	}

	return secret, nil
}
